def word_frequency(text: str) -> dict[str, int]:
    import string
    counts = {}
    for word in text.lower().split():
        cleaned = word.strip(string.punctuation)
        if cleaned:
            counts[cleaned] = counts.get(cleaned, 0) + 1
    return counts
